def agent_action(sandbox, agent_body, step_count):
    x, y = sandbox.get_sled_position()
    vx, vy = sandbox.get_sled_velocity()

    # Determine current target
    if not sandbox.get_checkpoint_a_reached() and not sandbox.get_checkpoint_b_reached():
        target_x, target_y = 17.5, 3.8  # Alpha checkpoint lower edge
    elif not sandbox.get_checkpoint_b_reached():
        target_x, target_y = 23.0, 2.5  # Beta checkpoint lower edge
    else:
        target_x, target_y = 30.0, 2.2  # Final target lower edge

    dx = target_x - x
    dy = target_y - y
    distance = math.hypot(dx, dy)

    if distance == 0:
        return

    direction = (dx / distance, dy / distance)

    # Calculate dot product between velocity and direction
    dot = vx * dx + vy * dy

    # Determine scaling factor based on distance and dot product
    K = 120  # Increased thrust for acceleration
    if distance > 20:
        K = 120
    elif distance > 10:
        K = 100
    elif distance > 5:
        K = 80
    else:
        K = 40  # Reduce thrust for final approach

    if dot < 0:
        scaling = 1.5  # Increase thrust when moving away
    else:
        scaling = 1.0  # Default scaling

    f1 = direction[0] * K * scaling
    f2 = direction[1] * K * scaling

    # Apply vertical adjustment to lift into target y-range
    if not sandbox.get_checkpoint_a_reached() and not sandbox.get_checkpoint_b_reached():
        target_y_min, target_y_max = 3.8, 4.5
    elif not sandbox.get_checkpoint_b_reached():
        target_y_min, target_y_max = 2.5, 3.2
    else:
        target_y_min, target_y_max = 2.2, 2.8

    # Vertical adjustment when below or above target y-range
    if y < target_y_min:
        # Need to lift up
        vertical_adjustment = (target_y_min - y) * 250  # Aggressive lift
        f2 += vertical_adjustment
    elif y > target_y_max:
        # Need to lower down
        vertical_adjustment = (y - target_y_max) * 250
        f2 -= vertical_adjustment

    # Apply the thrust
    sandbox.apply_thrust(f1, f2)
